export function nextGeneration(liveCells: Cell[]): Cell[] {
  const livingKeys = new Set(liveCells.map(key));

  const liveNeighborCount = (cell: Cell): number =>
    neighborsOf(cell).filter((neighbor) => livingKeys.has(key(neighbor))).length;

  // Only live cells and their neighbors can be alive next generation;
  // every other cell has zero live neighbors.
  const candidates = new Map<string, Cell>();
  for (const cell of liveCells) {
    for (const candidate of [cell, ...neighborsOf(cell)]) {
      candidates.set(key(candidate), candidate);
    }
  }

  const nextLiveCells: Cell[] = [];
  for (const [candidateKey, cell] of candidates) {
    const count = liveNeighborCount(cell);
    const isAlive = livingKeys.has(candidateKey);
    if (count === 3 || (isAlive && count === 2)) nextLiveCells.push(cell);
  }
  return nextLiveCells;
}
